// Edit these two lists
const feeds = [
  'https://hnrss.org/frontpage',
  'https://blog.n8n.io/rss/',
];
const keywords = ['automation', 'ai', 'api'];

return feeds.map(url => ({ json: { url, keywords } }));

const kw = $('Set feeds and keywords').first().json.keywords.map(k => k.toLowerCase());
const since = Date.now() - 864e5; const seen = new Set();
const items = $input.all().map(i => i.json).filter(j => { const d = Date.parse(j.isoDate || j.pubDate || 0); const t = ((j.title||'') + ' ' + (j.contentSnippet||'')).toLowerCase(); if (seen.has(j.link)) return false; seen.add(j.link); return d >= since && kw.some(k => t.includes(k)); });
if (!items.length) return [];
const text = `*Daily digest (${items.length})*\n` + items.slice(0, 25).map(j => `• <${j.link}|${j.title}>`).join('\n');
return [{ json: { text } }];
